def spring(n):
    for i in range(n): yield i
def strain(stream):
    for x in stream:
        if x % 2 == 0: yield x
count = sum(1 for _ in strain(spring(200000)))
print("strained buckets:", count)
assert count == 100000

vals = sorted((i*37) % 101 for i in range(400))
def pct(q):
    i = q*(len(vals)-1); lo = int(i)
    return vals[lo] + (vals[lo+1]-vals[lo])*(i-lo)
print("p50:", round(pct(.5), 1), "p99:", round(pct(.99), 1))
assert pct(.5) <= pct(.99)

def baskets(n, size):
    for i in range(0, n, size): yield range(i, min(i+size, n))
biggest, total = 0, 0
for b in baskets(5000, 250):
    batch = list(b); biggest = max(biggest, len(batch)); total += sum(batch)
print("biggest basket:", biggest, "| total:", total)
assert biggest == 250 and total == sum(range(5000))
